mapper.select:
SELECT e.*, d.name as department_name FROM sys_employee e LEFT JOIN sys_department d ON e.department_id = d.id WHERE e.deleted = 0
AND e.name LIKE CONCAT('%', #{query.name}, '%')
AND e.department_id = #{query.departmentId}
AND e.status = #{query.status}
AND e.position LIKE CONCAT('%', #{query.position}, '%')
ORDER BY e.create_time DESC
